use std::path::PathBuf;

use callisto_model::{DeclaredEdge, ProjectRoot};

pub mod ignore_walk;
mod membership;
pub mod root;

pub use ignore_walk::IgnoreWalkLocator;
pub use root::find_workspace_root;

pub trait ProjectLocator: Send + Sync {
    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError>;
    fn declared_edges(&self) -> Option<Vec<DeclaredEdge>> {
        None
    }
}

#[derive(Clone, Debug, thiserror::Error, miette::Diagnostic, PartialEq, Eq)]
#[non_exhaustive]
pub enum LocateError {
    #[error("workspace root not found starting from `{start}`")]
    #[diagnostic(
        code(E030),
        help(
            "No workspace root found. Ensure the directory tree contains a workspace manifest: \
             Cargo.toml with [workspace], package.json with a workspaces field, \
             pnpm-workspace.yaml, or a .moon directory."
        )
    )]
    WorkspaceRootNotFound { start: PathBuf },

    #[error("failed to walk filesystem under `{path}`: {message}")]
    #[diagnostic(code(E031))]
    Walk { path: PathBuf, message: String },

    #[error("project path `{path}` is outside the workspace root `{root}`")]
    #[diagnostic(code(E032))]
    OutsideWorkspaceRoot { path: PathBuf, root: PathBuf },

    /// A VCS operation failed during workspace location. This variant exists
    /// so that callers who need to distinguish filesystem-structure errors
    /// (WorkspaceRootNotFound, Walk) from VCS errors (e.g., a git repository
    /// that could not be opened or queried during locate) can do so.
    #[error("VCS error during workspace location: {0}")]
    #[diagnostic(code(E033))]
    Vcs(Box<callisto_vcs::VcsError>),

    #[error("moon CLI is unavailable or exited non-zero")]
    MoonUnavailable,

    #[error("Failed to parse moon project-graph output: {message}")]
    MoonOutputParse { message: String },

    #[error("Incompatible moon version found: {found}, required: {required}")]
    IncompatibleMoonVersion { found: String, required: String },

    #[error(transparent)]
    Graph(#[from] Box<crate::error::GraphError>),
}

impl From<callisto_vcs::VcsError> for LocateError {
    fn from(e: callisto_vcs::VcsError) -> Self {
        LocateError::Vcs(Box::new(e))
    }
}

name: 'Setup Callisto Environment'
description: 'Sets up Rust toolchain, Cargo cache, Moon, and Callisto CLI'
inputs:
  source:
    description: 'Where to obtain Callisto: local requires this checkout; release jobs must use local.'
    required: false
    default: 'auto'
  version:
    description: 'Version tag of Callisto to install'
    required: false
    default: 'latest'

runs:
  using: 'composite'
  steps:
    - name: Install Rust Toolchain & Cache
      # orin-dx/actions/setup-rust v1.1
      uses: orin-dx/actions/setup-rust@2521888266780dabc7f5fd4c32b02d6ab82849db
      with:
        components: clippy,rustfmt
        targets: wasm32-wasip1
        shared-key: "callisto-workspace-shared"
        save-if: "true"
      env:
        CARGO_INCREMENTAL: "0"
        CARGO_REGISTRY_SPARSE: "true"

    - name: Install Moon
      # moonrepo/setup-toolchain v0
      uses: moonrepo/setup-toolchain@261c62cb5b0f580c7be7c8cd0f023a2e96756095
      with:
        auto-install: true

    - name: Install or Build Callisto Binary
      shell: bash
      env:
        INPUT_CALLISTO_SOURCE: ${{ inputs.source }}
        INPUT_CALLISTO_VERSION: ${{ inputs.version }}
      run: | # zizmor: ignore[github-env] the PATH entry is a fixed child of the trusted runner temporary directory, not action input or downloaded archive content.
        # Install into $RUNNER_TEMP so the binary never lands inside the workspace
        # tree (preventing accidental git-staging by downstream steps that run
        # "git add -A").
        CALLISTO_BIN_DIR="${RUNNER_TEMP}/callisto-bin"
        mkdir -p "$CALLISTO_BIN_DIR"
        TAG_NAME="$INPUT_CALLISTO_VERSION"
        SOURCE="$INPUT_CALLISTO_SOURCE"

        if [[ "$SOURCE" != "auto" && "$SOURCE" != "local" ]]; then
          echo "::error::unsupported setup-callisto source '$SOURCE' (expected auto or local)"
          exit 1
        fi

        # Detect OS platform architecture for pre-built binaries
        OS_NAME=$(uname -s | tr '[:upper:]' '[:lower:]')
        ARCH_NAME=$(uname -m)

        if [[ "$OS_NAME" == "darwin" ]]; then
          if [[ "$ARCH_NAME" == "arm64" ]]; then
            ASSET_NAME="callisto-macos-aarch64.tar.gz"
          else
            ASSET_NAME="callisto-macos-amd64.tar.gz"
          fi
        elif [[ "$OS_NAME" == "linux" ]]; then
          ASSET_NAME="callisto-linux-amd64.tar.gz"
        elif [[ "$OS_NAME" == *"mingw"* || "$OS_NAME" == *"msys"* || "$OS_NAME" == *"windows"* ]]; then
          ASSET_NAME="callisto-windows-amd64.zip"
        else
          ASSET_NAME="callisto-linux-amd64.tar.gz"
        fi

        if [[ "$TAG_NAME" == "latest" ]]; then
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/latest/download/$ASSET_NAME"
        else
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/download/$TAG_NAME/$ASSET_NAME"
        fi

        # Derive a crates.io version spec from TAG_NAME: "latest" installs
        # whatever crates.io resolves as latest (no --version flag); an
        # explicit tag like "callisto-cli@0.5.0" strips the "callisto-cli@"
        # prefix down to the bare semver cargo install expects.
        CRATE_VERSION="${TAG_NAME#callisto-cli@}"

        # Pick a download destination whose extension matches ASSET_NAME
        # (under $RUNNER_TEMP, never the workspace) so the extraction step
        # below always has an archive it can actually open -- a hardcoded
        # ".tar.gz" path here previously masked the fact that Windows assets
        # are zip files, since tar -xzf can't read a zip regardless of what
        # the file on disk is really named.
        case "$ASSET_NAME" in
          *.zip)
            DOWNLOAD_DEST="${RUNNER_TEMP}/callisto.zip"
            ;;
          *.tar.gz)
            DOWNLOAD_DEST="${RUNNER_TEMP}/callisto.tar.gz"
            ;;
          *)
            DOWNLOAD_DEST="${RUNNER_TEMP}/callisto.tar.gz"
            ;;
        esac

        # Prioritize local repository build when inside the callisto monorepo
        if [[ -f "$GITHUB_WORKSPACE/Cargo.toml" ]] && grep -q "callisto-cli" "$GITHUB_WORKSPACE/Cargo.toml"; then
          echo "Building local callisto binary from current repository commit..."
          cargo build -p callisto-cli
          cp "$GITHUB_WORKSPACE/target/debug/callisto" "$CALLISTO_BIN_DIR/callisto"
        elif [[ "$SOURCE" == "local" ]]; then
          echo "::error::setup-callisto source=local requires a Callisto workspace checkout"
          exit 1
        elif curl -sL -f "$DOWNLOAD_URL" -o "$DOWNLOAD_DEST" 2>/dev/null; then
          # Match the extraction tool to ASSET_NAME's actual format; any
          # unrecognized extension defensively falls back to the previous
          # tar.gz behavior rather than erroring (the crates.io/cargo-install
          # fallback chain below already exists to absorb total failure).
          case "$ASSET_NAME" in
            *.zip)
              unzip -q "$DOWNLOAD_DEST" -d "$CALLISTO_BIN_DIR"
              ;;
            *.tar.gz)
              tar -xzf "$DOWNLOAD_DEST" -C "$CALLISTO_BIN_DIR"
              ;;
            *)
              tar -xzf "$DOWNLOAD_DEST" -C "$CALLISTO_BIN_DIR"
              ;;
          esac
          echo "Callisto downloaded from GitHub Releases ($DOWNLOAD_URL)"
        elif [[ "$TAG_NAME" == "latest" ]] && cargo install callisto-cli --locked --root "${RUNNER_TEMP}/callisto-cargo-install" --quiet; then
          echo "Callisto installed from crates.io (latest)"
          cp "${RUNNER_TEMP}/callisto-cargo-install/bin/callisto" "$CALLISTO_BIN_DIR/callisto"
        elif [[ "$TAG_NAME" != "latest" ]] && cargo install callisto-cli --version "$CRATE_VERSION" --locked --root "${RUNNER_TEMP}/callisto-cargo-install" --quiet; then
          echo "Callisto installed from crates.io ($CRATE_VERSION)"
          cp "${RUNNER_TEMP}/callisto-cargo-install/bin/callisto" "$CALLISTO_BIN_DIR/callisto"
        else
          echo "Installing from git source (crates.io install failed or was skipped)..."
          cargo install --git https://github.com/orin-dx/callisto.git callisto-cli --root "${RUNNER_TEMP}/callisto-cargo-install" --quiet
          cp "${RUNNER_TEMP}/callisto-cargo-install/bin/callisto" "$CALLISTO_BIN_DIR/callisto"
        fi

        echo "$CALLISTO_BIN_DIR" >> $GITHUB_PATH
        if [[ -f "$GITHUB_WORKSPACE/.github/callisto-problem-matcher.json" ]]; then
          echo "::add-matcher::$GITHUB_WORKSPACE/.github/callisto-problem-matcher.json"
        fi
name: 'Setup Callisto WASM'
description: 'Pre-downloads and caches callisto-moon.wasm from GitHub Releases for Moon integration'
inputs:
  version:
    description: 'Callisto WASM version to download (defaults to "latest")'
    required: false
    default: 'latest'
  dest:
    description: 'Destination path for callisto-moon.wasm'
    required: false
    default: '.moon/cache/ext/callisto-moon.wasm'

outputs:
  path:
    description: 'Path to the local cached callisto-moon.wasm file'
    value: ${{ steps.download-wasm.outputs.path || inputs.dest }}

runs:
  using: 'composite'
  steps:
    - name: Cache Callisto WASM
      id: cache-wasm
      # actions/cache v4.2.3
      uses: actions/cache@5a3ec84eff668545956fd18022155c47e93e2684
      with:
        path: ${{ inputs.dest }}
        key: ${{ runner.os }}-callisto-wasm-${{ inputs.version }}

    - name: Download Callisto WASM Plugin
      id: download-wasm
      if: steps.cache-wasm.outputs.cache-hit != 'true'
      shell: bash
      env:
        INPUT_WASM_DEST: ${{ inputs.dest }}
        INPUT_WASM_VERSION: ${{ inputs.version }}
      run: |
        DEST_PATH="$INPUT_WASM_DEST"
        mkdir -p "$(dirname "$DEST_PATH")"
        TAG_NAME="$INPUT_WASM_VERSION"

        if [[ "$TAG_NAME" == "latest" ]]; then
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/latest/download/callisto-moon.wasm"
        else
          DOWNLOAD_URL="https://github.com/orin-dx/callisto/releases/download/${TAG_NAME}/callisto-moon.wasm"
        fi

        echo "Downloading Callisto WASM plugin from $DOWNLOAD_URL to $DEST_PATH..."
        if ! curl -sL -f "$DOWNLOAD_URL" -o "$DEST_PATH"; then
          echo "Release binary asset not found. Compiling Callisto WASM plugin locally..."
          rustup target add wasm32-wasip1 2>/dev/null || true
          cargo build -p callisto-moon --target wasm32-wasip1 --features pdk --release
          cp target/wasm32-wasip1/release/callisto_moon.wasm "$DEST_PATH"
        fi

        echo "path=$DEST_PATH" >> $GITHUB_OUTPUT
            for (c in sum) {
              pct = (cov[c]/sum[c]*100)
              status = (pct+0 < threshold+0) ? "FAIL" : "pass"
              printf "%s\t%d\t%d\t%.2f\t%s\n", c, sum[c], cov[c], pct, status
            }
          }
        ' | sort)
    echo "$report" | awk -F'\t' '{printf "%-25s lines=%-6s covered=%-6s cover=%6s%%  %s\n", $1, $2, $3, $4, $5}'
    echo "$report" | grep -q FAIL && exit 1 || exit 0

# Clean build targets, Moon task caches, and generated artifacts
clean:
    moon clean 2>/dev/null || true
    cargo clean
    rm -f lcov.info callisto-schema.json

# Fast pre-commit hook validation (<500ms formatting check)
pre-commit: fmt-check

# Pre-push hook validation: formatting check plus clippy on affected projects only
pre-push: fmt-check lint-affected

# Install native Git pre-commit and pre-push hooks
hooks:
    @echo '#!/bin/sh\njust pre-commit' > .git/hooks/pre-commit
    @chmod +x .git/hooks/pre-commit
    @echo '#!/bin/sh\njust pre-push' > .git/hooks/pre-push
    @chmod +x .git/hooks/pre-push
    @echo "Git pre-commit and pre-push hooks installed successfully."

# Run full local CI verification pipeline via moon and just
ci: fmt-check lint test audit doc-check wasm-check coverage

# Same as `ci`, minus `coverage`. Real CI (callisto-ci.yml) already runs
# coverage as its own parallel job on a separate runner; locally it's a
# third full-workspace recompile under llvm-cov instrumentation tacked onto
# the end of a serial pipeline. Use this for everyday pre-PR checks;
# coverage numbers are a reporting concern, not something every local run
# needs to regenerate.
ci-fast: fmt-check lint test audit doc-check wasm-check
